<section class="container page-section notification-page">
 <div class="page-heading mb-4"><div><p class="eyebrow"><i class="bi bi-chat-square-heart me-2" aria-hidden="true"></i>Kabar untukmu</p><h1 class="h2">Kotak notifikasi</h1><p class="text-secondary mb-0">Transaksi, dukungan, dan informasi akun dalam satu tempat. Diperbarui berkala; status terbaru ada di halaman detail.</p></div></div>
 <nav class="monitor-tabs d-flex flex-wrap gap-2 mb-4" aria-label="Status pesan"><?php foreach(array('unread'=>'Belum dibaca','read'=>'Sudah dibaca','all'=>'Semua pesan') as $key=>$label): ?><a class="btn <?php echo $key===$status?'btn-primary':'btn-outline-primary'; ?>" href="<?php echo site_url('notifikasi').'?status='.$key; ?>"<?php echo $key===$status?' aria-current="page"':''; ?>><?php echo $label; ?></a><?php endforeach; ?></nav>
 <?php if($inbox['max_id']): ?><?php echo form_open('notifikasi',array('class'=>'feature-card d-flex flex-wrap align-items-center gap-3 mb-4')); ?><input type="hidden" name="action" value="all"><input type="hidden" name="id" value="<?php echo (int)$inbox['max_id']; ?>"><div class="form-check"><input class="form-check-input" type="checkbox" name="confirm" value="1" id="all-read" required><label class="form-check-label" for="all-read">Tandai semua pesan saat ini sudah dibaca</label></div><button class="btn btn-teal" type="submit"><i class="bi bi-check2-all me-2" aria-hidden="true"></i>Terapkan</button><?php echo form_close(); ?><?php endif; ?>
 <?php if(!$inbox['rows']): ?><div class="empty-card"><span class="empty-icon"><i class="bi bi-envelope-check" aria-hidden="true"></i></span><h2 class="h4">Tidak ada pesan pada tab ini</h2><p>Kabar baru akan muncul saat ada kegiatan terkait akunmu. Tidak ada pesan lama yang dihapus oleh tombol tandai dibaca.</p></div><?php endif; ?>
 <div class="vstack gap-3"><?php foreach($inbox['rows'] as $n): ?><article class="feature-card notification-item <?php echo $n['read_at']?'is-read':'is-unread'; ?>"><div class="d-flex gap-3"><span class="feature-icon feature-coral flex-shrink-0"><i class="bi <?php echo array('payments'=>'bi-receipt','donations'=>'bi-heart','help'=>'bi-chat-dots','visitors'=>'bi-bar-chart')[$n['category']]??'bi-bell'; ?>" aria-hidden="true"></i></span><div class="min-w-0"><p class="small text-secondary mb-1"><?php echo html_escape(study_format_datetime($n['created_at'])); ?> · <?php echo $n['read_at']?'Sudah dibaca':'Baru'; ?></p><h2 class="h5"><?php echo html_escape($n['title']); ?></h2><p class="text-break"><?php echo html_escape($n['body']); ?></p><div class="d-flex flex-wrap gap-2"><a class="btn btn-primary" href="<?php echo html_escape(site_url($n['path'])); ?>">Buka detail</a><?php if(!$n['read_at']): ?><?php echo form_open('notifikasi'); ?><input type="hidden" name="action" value="read"><input type="hidden" name="id" value="<?php echo (int)$n['id']; ?>"><button class="btn btn-outline-secondary" type="submit"><i class="bi bi-check2 me-1" aria-hidden="true"></i>Sudah dibaca</button><?php echo form_close(); ?><?php endif; ?></div></div></div></article><?php endforeach; ?></div>
 <nav class="d-flex flex-wrap align-items-center gap-3 mt-4" aria-label="Halaman notifikasi"><?php foreach(array(-1=>'Sebelumnya',1=>'Berikutnya') as $step=>$label): if($inbox['page']+$step>=1 && $inbox['page']+$step<=max(1,ceil($inbox['total']/20))): ?><a class="btn btn-outline-primary" href="<?php echo html_escape(site_url('notifikasi').'?'.http_build_query(array('status'=>$status,'halaman'=>$inbox['page']+$step))); ?>"><?php echo $label; ?></a><?php endif; endforeach; ?><span><?php echo (int)$inbox['total']; ?> pesan · halaman <?php echo (int)$inbox['page']; ?></span></nav>
</section>
